/**
 * parallel-plan — the record type of schema id `specstride.parallel-plan/1`, annex D, §D.3.
 *
 * Generated by `scripts/types.mjs` from `schemas/parallel-plan.schema.json` (research.md,
 * D-1) — do not edit; re-run the `build` script of the package instead. The
 * fields keep the meaning, the type in words and the required cell of the
 * annex as documentation.
 */
export interface ParallelPlan {
  /**
   * Schema id
   *
   * Type in words: Text.
   */
  schema: string;
  /**
   * Identifier
   *
   * Type in words: Text.
   */
  runId: string;
  /**
   * Hash of the plan, which is also an event
   *
   * Type in words: Text.
   */
  hash: string;
  /**
   * Worker count in force (default 2; the ceiling is `loop.parallel.workersMax`, default 4)
   *
   * Type in words: Whole number.
   */
  workers: number;
  /**
   * Per phase: its groups, its serial tasks, and the ceiling of the speed-up under equal task cost
   *
   * Type in words: List of records.
   */
  phases: Array<{
    /**
     * Per group: ordinal, and the task ids in the order of the tasks at launch. A group holds at least 2 and at most `workers` tasks, all consecutive and admitted
     *
     * Type in words: List of records.
     */
    groups: unknown[];
    /**
     * Per candidate task: id, write scope (path prefixes relative to the workspace root), the source of the scope (consumer declaration, or the task's own text at launch), and the verdict of every admission check with its detail
     *
     * Type in words: List of records.
     */
    tasks: unknown[];
    /**
     * Tasks made serial, each with the reason
     *
     * Type in words: List of records.
     */
    serial: unknown[];
  }>;
  /**
   * When the layer is off for the run: the reason, from the closed set of fallback reasons
   *
   * Type in words: Member of a closed set, or null.
   */
  fallback: string | null;
}
